      "content": "// SPDX-License-Identifier: AGPL-3.0-only
pragma solidity ^0.8.24;

/// @title PerpConstants — Managed Futures Desk parameters (specs/perp.md)
/// @notice Single source of truth for every §13 number. Items marked TUNE are
///         `DEFAULT — TUNE` per the spec: retuned by the human only via the
///         named constant, never an owner function. Funding-curve and cap
///         values were delegated to agent judgement by the human (2026-07-16)
///         and remain TUNE.
library PerpConstants {
    uint256 internal constant WAD = 1e18;
    uint256 internal constant BPS = 10_000;
    /// @dev Margin token (tNET now, wsNET-alike) uses NET's 9 decimals.
    uint256 internal constant MARGIN_UNIT = 1e9;
    /// @dev sNET dividend index base (index() starts at 1e9).
    uint256 internal constant INDEX_UNIT = 1e9;

    // ── Collateral valuation (perp.md §4) ──
    /// @dev Haircut h applied to margin spot value. TUNE.
    uint256 internal constant HAIRCUT_BPS = 1_500;
    /// @dev Premium-credit cap C, in multiples of the backing floor. TUNE.
    uint256 internal constant PREMIUM_CAP_X = 2;

    // ── Position mechanics (perp.md §5) ──
    /// @dev Max leverage L_max. TUNE.
    uint256 internal constant MAX_LEVERAGE_X = 10;
    /// @dev Maintenance margin mm as a fraction of notional. TUNE.
    uint256 internal constant MAINTENANCE_BPS = 100;
    /// @dev Taker fee on notional, charged on open and close. TUNE.
    uint256 internal constant TAKER_FEE_BPS = 5;
    /// @dev Margin-call penalty on notional (perp.md §8.1). TUNE.
    uint256 internal constant LIQ_PENALTY_BPS = 100;
    /// @dev Share of each margin-call penalty retained as the Clearing
    ///      Reserve (perp.md §8.3); the rest routes to fees. TUNE.
    uint256 internal constant CLEARING_RESERVE_CUT_BPS = 5_000;

    // ── Carry / funding (perp.md §5; values delegated, TUNE) ──
    /// @dev Carry accrual period (matches the protocol epoch cadence).
    uint256 internal constant CARRY_PERIOD = 8 hours;
    /// @dev Max carry per period at full one-sided skew, as WAD fraction of
    ///      notional (0.1% per 8h). TUNE.
    uint256 internal constant CARRY_MAX_PER_PERIOD_WAD = 0.001e18;
    /// @dev Share of collected carry skimmed to the fee route (perp.md §5).
    uint256 internal constant CARRY_SKIM_BPS = 1_000;

    // ── Risk caps (perp.md §7; values delegated, TUNE) ──
    /// @dev Per-market open-interest cap, USD notional as WAD. TUNE.
    uint256 internal constant OI_CAP_USD_WAD = 2_000_000e18;
    /// @dev Max |net skew| the vault may underwrite, as bps of vault equity
    ///      (USD-valued). TUNE.
    uint256 internal constant UTIL_MAX_BPS = 8_000;
    /// @dev Vault drawdown breaker: new opens halt when equity falls below
    ///      this fraction of cumulative subscribed capital. TUNE.
    uint256 internal constant DRAWDOWN_HALT_BPS = 2_500;

    // ── tNET faucet (perp.md §13.2) ──
    uint256 internal constant FAUCET_AMOUNT = 10_000e9;
    uint256 internal constant FAUCET_COOLDOWN = 24 hours;

    // ── SPCX index staleness (perp.md §13.4; market-hours-aware) ──
    /// @dev Conservative "feed should be updating" window, UTC, weekdays:
    ///      14:00–20:30. Sits inside US-equity hours under both EST and EDT,
    ///      so a DST shift never marks a live session stale. TUNE.
    uint256 internal constant SESSION_OPEN_UTC_MIN = 14 hours;
    uint256 internal constant SESSION_CLOSE_UTC_MIN = 20 hours + 30 minutes;
    /// @dev Max feed age while the session window is open. TUNE.
    ///      Revised 2026-07-21 (was 45 minutes): the SPCX feed is
    ///      deviation-gated and sat quiet for 49 minutes mid-session on day
    ///      one, halting the desk on a healthy feed. 4 hours still catches a
    ///      dead feed same-session; the keeper's perpWatch alerts besides.
    uint256 internal constant INDEX_MAX_AGE_ACTIVE = 4 hours;
    /// @dev Max feed age outside the session window (covers the weekend
    ///      close→open gap of ~65h with margin). TUNE.
    uint256 internal constant INDEX_MAX_AGE_IDLE = 80 hours;
}
