    "src/perp/interfaces/IPerpExternal.sol": {
      "content": "// SPDX-License-Identifier: AGPL-3.0-only
pragma solidity ^0.8.24;

/// @notice Narrow, read-only views of the live protocol consumed by the
///         Managed Futures Desk. The desk's ONLY interaction with live
///         contracts is through these `view` calls (perp.md §13.7).
interface IPairOracleView {
    /// @dev WAD price of 1 whole NET in USDG; reverts fail-closed when the
    ///      TWAP window is out of band.
    function twapNetUsdg() external view returns (uint256);
}

interface ITreasuryView {
    /// @dev WAD backing (RFV) per whole NET.
    function backingPerToken() external view returns (uint256);
}

interface IsNETIndexView {
    /// @dev Dividend index, 1e9 base (starts at 1e9).
    function index() external view returns (uint256);
}

/// @notice Chainlink AggregatorV3Interface (consumed per the official
///         Robinhood Chain oracle docs; address from the sdk registry).
interface IAggregatorV3 {
    function decimals() external view returns (uint8);
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

/// @notice Minimal ERC-20 surface used across the desk.
interface IERC20Minimal {
    function totalSupply() external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}

/// @notice Staking surface needed by Zap (real protocol contract).
interface IStakingMinimal {
    function stake(address to, uint256 amount) external returns (uint256);
    function warmupEpochs() external view returns (uint256);
}
